export type Chunk = { id: string; source: string; text: string };
export type Ranked = Chunk & { score: number };
export type Answer = { text: string; citations: string[] };
export type Embedder = { (text: string): number[] };
export type Completer = { (prompt: string): string };

export function chunkDocument(source: string, text: string): Chunk[] {
    // TODO: split the document into overlapping chunks
    return [{ id: source + "#0", source: source, text: text }];
}

export function rankChunks(query: number[], chunks: Chunk[], embed: Embedder): Ranked[] {
    // TODO: score each chunk and return the best matches
    return chunks.map(function scored(chunk) {
        return { ...chunk, score: 0 };
    });
}

export function buildPrompt(question: string, ranked: Ranked[]): string {
    const context = ranked.map(function line(chunk) {
        return chunk.text;
    }).join("\n");
    return "Use these notes to answer the question:\n" + context + "\nQuestion: " + question;
}

export function answer(question: string, ranked: Ranked[], complete: Completer): Answer {
    // TODO: cite the sources that support the answer
    return { text: complete(buildPrompt(question, ranked)), citations: [] };
}
